P = {e['id']: e for e in json.load(open(f'{SP}/passages.json', encoding='utf-8'))}
SH = "#bu_load_prev{display:none!important} div.nomargin:has(#bu_tashkeel){display:none!important} .heading-title.heading-border{display:none!important} html,body,*{scroll-behavior:auto!important}"
S = "https://shamela.ws/book/"
def sg(f, t, keys=(), alts=()):
    d = {"from": f, "to": t, "keys": list(keys)}
    if alts: d["alts"] = list(alts)
    return d
def sp(i, book, page, segs): return dict(id=i, url=f'{S}{book}/{page}', css=SH, minW=400, segments=segs)
def P_(pid, **kw):
    e = P[pid]; d = sg(e['from_'], e['to'], e['keys'], e['alts']); d.update(kw); return d
def X(pid, f=None, t=None, keys=None, alts=None):
    e = P[pid]; return sg(f or e['from_'], t or e['to'], e['keys'] if keys is None else keys, e['alts'] if alts is None else alts)
